package java.util;
public class Date implements java.io.Serializable,Cloneable,Comparable<Date> {private long time;public Date(){this(System.currentTimeMillis());}public Date(long time){this.time=time;}public long getTime(){return time;}public void setTime(long time){this.time=time;}public boolean before(Date when){return time<when.time;}public boolean after(Date when){return time>when.time;}public int compareTo(Date another){return time<another.time?-1:time==another.time?0:1;}public boolean equals(Object o){return o instanceof Date&&time==((Date)o).time;}public int hashCode(){return (int)(time^(time>>>32));}public Object clone(){return new Date(time);}}
